    /// <summary>长属性计算值的 CSS 文本（DevTools 的 getComputedStyle）；简写返回空串。</summary>
    public string GetPropertyValueText(CssPropertyId id)
    {
        switch (id)
        {
            case CssPropertyId.Display: { var x = BoxGroup.Display; return KeywordTables.CssDisplay.NameOf((int)x); }
            case CssPropertyId.BoxSizing: { var x = BoxGroup.BoxSizing; return KeywordTables.CssBoxSizing.NameOf((int)x); }
            case CssPropertyId.Width: { var x = BoxGroup.Width; return x.ToString(); }
            case CssPropertyId.Height: { var x = BoxGroup.Height; return x.ToString(); }
            case CssPropertyId.MinWidth: { var x = BoxGroup.MinWidth; return x.ToString(); }
            case CssPropertyId.MinHeight: { var x = BoxGroup.MinHeight; return x.ToString(); }
            case CssPropertyId.MaxWidth: { var x = BoxGroup.MaxWidth; return x.ToString(); }
            case CssPropertyId.MaxHeight: { var x = BoxGroup.MaxHeight; return x.ToString(); }
            case CssPropertyId.MarginTop: { var x = BoxGroup.MarginTop; return x.ToString(); }
            case CssPropertyId.MarginRight: { var x = BoxGroup.MarginRight; return x.ToString(); }
            case CssPropertyId.MarginBottom: { var x = BoxGroup.MarginBottom; return x.ToString(); }
            case CssPropertyId.MarginLeft: { var x = BoxGroup.MarginLeft; return x.ToString(); }
            case CssPropertyId.PaddingTop: { var x = BoxGroup.PaddingTop; return x.ToString(); }
            case CssPropertyId.PaddingRight: { var x = BoxGroup.PaddingRight; return x.ToString(); }
            case CssPropertyId.PaddingBottom: { var x = BoxGroup.PaddingBottom; return x.ToString(); }
            case CssPropertyId.PaddingLeft: { var x = BoxGroup.PaddingLeft; return x.ToString(); }
            case CssPropertyId.OverflowX: { var x = BoxGroup.OverflowX; return KeywordTables.CssOverflow.NameOf((int)x); }
